void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord/iResolution.xy)*2. -1.;
    uv.x *= iResolution.x/iResolution.y;

    vec3 lightColour = vec3(0.569,0.255,0.675);

    vec3 lightpos = vec3(cos(iTime),sin(iTime),-1);

    vec3 normal = normalize(vec3(uv, sqrt(1.0 - dot(uv, uv)))); 

    vec3 lighting = max(dot(lightpos,normal),0.) * lightColour;
    lighting = pow(lighting,vec3(1./1.5));
    vec3 col = vec3(1.) * lighting;



    fragColor = vec4(col,1.0);
}
